// Normaliza el payload de Meta o TikTok a un formato común
const item = $input.first().json;
const isMeta = !!item.entry;
let normalized;
if (isMeta) {
  const change = item.entry[0].changes[0].value;
  normalized = {
    platform: item.entry[0].id ? 'facebook' : 'instagram',
    handle: change.from?.username || change.from?.id,
    comment_text: change.message || change.text,
    post_url: change.post_id || change.media?.id
  };
} else {
  normalized = {
    platform: 'tiktok',
    handle: item.user?.unique_id,
    comment_text: item.text,
    post_url: item.video_id
  };
}
return [{ json: normalized }];

// Filtro rápido por keywords antes de gastar una llamada a LLM
const text = ($input.first().json.comment_text || '').toLowerCase();
const keywords = ['precio','cuanto','cuánto','cost','price','disponible','cotiza','interesad','dm','info','vale','$'];
const matched = keywords.some(k => text.includes(k));
return [{ json: { ...$input.first().json, keyword_matched: matched } }];

const llm = JSON.parse($input.first().json.choices?.[0]?.message?.content || '{}');
const src = $('Keyword Prefilter').first().json;
return [{ json: { ...src, detected_intent: llm.intent, draft_message: llm.suggested_reply } }];
